function (settings, time, ctx) {
  // ---------- SETTINGS ----------
  var MULTIPLIER    = settings.multiplier.value;      // value * multiplier (1 = escRPM as is; gear ratio, pole correction)
  var DIGITS        = settings.digits.value;          // decimal places of the value
  var AUTO_MAX      = settings.auto_max.value;        // dial maximum from the whole flight (rounded up to whole steps); off = Max RPM
  var MAX_RPM       = settings.max_rpm.value;         // dial maximum when Auto max is off (or no data yet)
  var SMOOTH_MS     = settings.smooth_ms.value;       // moving average window for the value in ms (0 = off)
  var PEAK_HOLD     = settings.peak_hold.value;       // show the momentary maximum with a fainter marker + ghost arc
  var HOLD_MS       = settings.hold_ms.value;         // how long the peak marker stays at the maximum before it starts sliding (ms)
  var SLIDE_SPEED   = settings.slide_speed.value;     // constant slide speed towards the current value, in % of the dial per second (100 = whole dial in 1 s)
  var PEAK_COLOR    = settings.peak_color.value;      // peak marker color
  var PEAK_OPACITY  = settings.peak_opacity.value;    // peak marker / ghost arc opacity 0..1 (fades out as it reaches the value)
  var SHOW_PEAK_VAL = settings.show_peak_value.value; // print the peak value under the unit while the marker is visible
  var SWEEP         = settings.sweep.value;           // dial sweep in degrees (270 = opening at the bottom)
  var MAJOR         = settings.major_tick.value;      // RPM between dial numbers (0 = auto; raised automatically so there are at most 20 numbers)
  var MINOR         = settings.minor_ticks.value;     // small ticks per number step (1 = one tick halfway, 0 = none)
  var DIVISOR       = settings.dial_divisor.value;    // dial numbers = RPM / divisor: 1 | 100 | 1000
  var LABEL         = settings.label.value;           // small caption above the value ('' = none)
  var UNIT          = settings.unit.value;            // unit text under the value ('' = none)
  var TRACK_COLOR   = settings.track_color.value;     // background arc color
  var FILL_COLOR    = settings.fill_color.value;      // filled arc color (0 .. current value)
  var MARKER_COLOR  = settings.marker_color.value;    // marker line at the end of the filled arc
  var MARKER_GAP    = settings.marker_gap.value;      // gap between the marker line and the center disc at the default 320x320 size; scales with the widget
  var CENTER_COLOR  = settings.center_color.value;    // center disc color
  var TEXT_COLOR    = settings.text_color.value;      // value / unit color
  var NUM_COLOR     = settings.number_color.value;    // dial numbers and small ticks
  var FONT          = settings.font.value;            // font family
  var VALUE_SIZE    = settings.value_size.value;      // value font size at the default 320x320 size; scales with the widget
  var LABEL_SIZE    = settings.label_size.value;      // caption font size at the default size; scales with the widget
  var PEAK_SIZE     = settings.peak_size.value;       // peak value ("MAX") font size at the default size; scales with the widget
  var NUM_SIZE      = settings.number_size.value;     // dial number font size at the default size; scales with the widget
  var TRACK_WIDTH   = settings.track_width.value;     // arc thickness at the default 320x320 size; scales with the widget
  var OPACITY       = settings.opacity.value;         // whole-widget opacity 0..1 (1 = opaque)
  var MAX_LABELS = 20;                                // hard cap on the number of dial numbers
  // -------------------------------
  var W = ctx.width, H = ctx.height, S = Math.min(W, H), scale = S / 320;
  // outer radius: leave room for the marker line, which reaches 0.2 tw past the track plus half of its
  // own stroke (0.19 tw, round cap) — the box clips everything outside it, at the top as well as at 90 deg
  var tw = TRACK_WIDTH * scale;
  var cx = W / 2, cy = H / 2, R = S / 2 - tw * 0.4 - 1.5 * scale;
  var col = ctx.columns[0];
  var s = ctx.state, i;

  // ---- current value (optionally smoothed) ----
  var cur = ctx.values[0];
  if (SMOOTH_MS > 0 && col && typeof cur === 'number') {   // outside the flight ctx.range still returns the edge sample: keep "--"
    var sam = ctx.range(col, time - SMOOTH_MS / 2, time + SMOOTH_MS / 2, 200) || [], sum = 0, cnt = 0;
    for (i = 0; i < sam.length; i++) if (typeof sam[i].v === 'number') { sum += sam[i].v; cnt++; }
    if (cnt) cur = sum / cnt;
  }
  if (typeof cur === 'number') cur = cur * MULTIPLIER; else cur = undefined;

  // ---- dial maximum + number step (cached per flight) ----
  // smallest "nice" step (1, 2, 2.5, 5 x 10^n) >= minStep that gives at most maxCount steps over range
  function niceStep(range, minStep, maxCount) {
    var mags = [1, 2, 2.5, 5], mag = 1, k;
    while (mag * 1e6 < minStep) mag *= 10;
    for (k = 0; k < 400; k++) {
      var step = mags[k % 4] * mag;
      if (step >= minStep && range / step <= maxCount) return step;
      if (k % 4 === 3) mag *= 10;
    }
    return range;
  }
  var key = col + '|' + MULTIPLIER + '|' + AUTO_MAX + '|' + MAX_RPM + '|' + MAJOR + '|' + ctx.dataVersion;
  if (s.key !== key) {
    var mx = MAX_RPM > 0 ? MAX_RPM : 10000, auto = false;
    if (AUTO_MAX && col) {
      var st = ctx.stats(col);
      if (st && typeof st.max === 'number' && st.max * MULTIPLIER > 0) { mx = st.max * MULTIPLIER; auto = true; }
    }
    var mj = MAJOR > 0 ? niceStep(mx, MAJOR, MAX_LABELS) : niceStep(mx, 0, 6);
    if (auto) mx = Math.max(mj, Math.ceil(mx / mj - 1e-9) * mj);   // whole number of steps
    s.max = mx; s.major = mj; s.key = key; s.staticKey = null;
  }
  var MAX = s.max, major = s.major;

  // ---- momentary maximum (classic peak hold): the marker rides on the value, stays HOLD_MS after the
  //      last real rise, then slides down at a constant speed until it meets the value again. Replayed from
  //      the telemetry history every frame (deterministic: seeking and export give the same frames) ----
  //      The replay runs on the same smoothed series the value shows, and the hold is re-armed only by a
  //      real rise (>= 1 % of the dial above the last trough), never by the marker catching up with the value.
  var peak = cur, alpha = 0;
  if (PEAK_HOLD && typeof cur === 'number' && col) {
    var speed = Math.max(1e-6, SLIDE_SPEED / 100 * MAX / 1000);          // RPM per ms
    var span = HOLD_MS + MAX / speed;                                     // after this long any older state has converged
    var half = SMOOTH_MS > 0 ? SMOOTH_MS / 2 : 0;
    var raw = ctx.range(col, time - span - half, time + half, 2000) || [];
    var ser = raw, j;
    if (half > 0) {                                                        // centered moving average, O(n)
      ser = []; var lo = 0, hi = 0, ssum = 0, scnt = 0;
      for (j = 0; j < raw.length; j++) {
        var tj = raw[j].t;
        while (hi < raw.length && raw[hi].t <= tj + half) { if (typeof raw[hi].v === 'number') { ssum += raw[hi].v; scnt++; } hi++; }
        while (lo < raw.length && raw[lo].t < tj - half) { if (typeof raw[lo].v === 'number') { ssum -= raw[lo].v; scnt--; } lo++; }
        ser.push({ t: tj, v: scnt > 0 ? ssum / scnt : raw[j].v });
      }
    }
    var eps = MAX * 0.01, pk = null, trough = 0, lastT = 0, lastRise = -1e12;
    for (i = 0; i < ser.length; i++) {
      var v = ser[i].v, t = ser[i].t;
      if (typeof v !== 'number' || t > time) continue;
      v = v * MULTIPLIER;
      if (pk === null) { pk = v; trough = v; lastT = t; continue; }
      if (t - lastRise > HOLD_MS) pk -= speed * (t - Math.max(lastT, lastRise + HOLD_MS));
      if (v >= pk) {                                                       // marker rides on the value
        pk = v;
        if (v < trough) trough = v;
        if (v - trough >= eps) lastRise = t;                               // a real rise above the trough arms the hold
      } else trough = v;                                                   // marker above the value: the value itself is the reference
      lastT = t;
    }
    if (pk !== null) {
      if (time - lastRise > HOLD_MS) pk -= speed * (time - Math.max(lastT, lastRise + HOLD_MS));
      peak = Math.min(MAX, Math.max(cur, pk));
    }
    alpha = PEAK_OPACITY * Math.min(1, (peak - cur) / (MAX * 0.02));
    if (alpha < 0.02) alpha = 0;
  }

  // ---- geometry (0 deg = 12 o'clock, clockwise) ----
  var Rt = R - tw / 2, a0 = -SWEEP / 2, rc = R * 0.44;
  var ov = 1.5 * scale / Rt * 180 / Math.PI;                              // ~1.5 px of arc, to overlap abutting shapes
  var fw = tw + 1.5 * scale;                                              // fill slightly wider than the track: hides the light anti-aliased track edges under it
  function ang(v) { var f = Math.max(0, Math.min(1, v / MAX)); return a0 + f * SWEEP; }
  function pt(r, a) { var t = a * Math.PI / 180; return [(cx + r * Math.sin(t)).toFixed(2), (cy - r * Math.cos(t)).toFixed(2)]; }
  function arc(r, a1, a2, color, width, cap, extra) {
    if (a2 - a1 < 0.05) return '';
    var p1 = pt(r, a1), p2 = pt(r, a2);
    return '<path d="M' + p1[0] + ',' + p1[1] + ' A' + r.toFixed(2) + ',' + r.toFixed(2) + ' 0 ' + ((a2 - a1) > 180 ? 1 : 0) + ' 1 ' + p2[0] + ',' + p2[1]
      + '" fill="none" stroke="' + color + '" stroke-width="' + width.toFixed(2) + '" stroke-linecap="' + cap + '"' + (extra || '') + '/>';
  }
  function marker(a, color, extra) {
    var p1 = pt(rc + MARKER_GAP * scale, a), p2 = pt(Rt + tw * 0.7, a);
    return '<line x1="' + p1[0] + '" y1="' + p1[1] + '" x2="' + p2[0] + '" y2="' + p2[1] + '" stroke="' + color + '" stroke-width="' + (tw * 0.38).toFixed(2) + '" stroke-linecap="round"' + (extra || '') + '/>';
  }
  function num(v) { var d = v / DIVISOR; return (Math.abs(d - Math.round(d)) < 1e-6) ? String(Math.round(d)) : d.toFixed(1); }

  // ---- static part: track, ticks, numbers, center disc (built once per size / look) ----
  var fs = VALUE_SIZE * scale;
  var staticKey = W + 'x' + H + '|' + MAX + '|' + major + '|' + MINOR + '|' + DIVISOR + '|' + SWEEP + '|' + TRACK_COLOR + '|' + CENTER_COLOR + '|' + NUM_COLOR + '|' + FONT + '|' + fs + '|' + NUM_SIZE + '|' + tw;
  if (s.staticKey !== staticKey) {
    var st2 = arc(Rt, a0, a0 + SWEEP, TRACK_COLOR, tw, 'round');
    var minor = MINOR >= 0 ? Math.round(MINOR) + 1 : 1;
    var tick = major / minor, total = Math.floor(MAX / tick + 1e-9);
    if (total > 200) { minor = 1; tick = major; total = Math.floor(MAX / tick + 1e-9); }
    var nfs = NUM_SIZE * scale;
    for (i = 0; i <= total; i++) {
      var val = i * tick, a = ang(val);
      if (i % minor === 0) {
        var q = pt(Rt - tw * 0.5 - nfs * 0.85, a);
        st2 += '<text x="' + q[0] + '" y="' + q[1] + '" fill="' + NUM_COLOR + '" font-size="' + nfs.toFixed(1) + '" text-anchor="middle" dominant-baseline="central">' + num(val) + '</text>';
      } else {
        var q1 = pt(Rt - tw * 0.5 - nfs * 0.45, a), q2 = pt(Rt - tw * 0.5 - nfs * 1.15, a);
        st2 += '<line x1="' + q1[0] + '" y1="' + q1[1] + '" x2="' + q2[0] + '" y2="' + q2[1] + '" stroke="' + NUM_COLOR + '" stroke-width="' + (1.5 * scale).toFixed(2) + '" stroke-linecap="round"/>';
      }
    }
    st2 += '<circle cx="' + cx + '" cy="' + cy + '" r="' + rc.toFixed(2) + '" fill="' + CENTER_COLOR + '"/>';
    s.staticSvg = st2; s.staticKey = staticKey;
  }

  // ---- dynamic part ----
  var out = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" style="font-family:' + FONT + ';opacity:' + OPACITY + '">' + s.staticSvg;
  if (typeof cur === 'number') {
    var ac = ang(cur);
    if (alpha > 0) {
      var ap = ang(peak);
      out += arc(Rt, ac - ov, ap, FILL_COLOR, fw, 'butt', ' stroke-opacity="' + (alpha * 0.5).toFixed(2) + '"');
      out += marker(ap, PEAK_COLOR, ' stroke-opacity="' + alpha.toFixed(2) + '"');
    }
    // filled arc: butt ends so it stops exactly at the marker; the rounded start is a half disc that
    // bulges only backwards (before zero), so at low values nothing sticks out past the marker
    var t0 = a0 * Math.PI / 180, hx = cx + Rt * Math.sin(t0), hy = cy - Rt * Math.cos(t0), hr = fw / 2;
    var nx = Math.sin(t0) * hr, ny = -Math.cos(t0) * hr;                  // radial half-width vector
    out += '<path d="M' + (hx + nx).toFixed(2) + ',' + (hy + ny).toFixed(2) + ' A' + hr.toFixed(2) + ',' + hr.toFixed(2) + ' 0 0 0 ' + (hx - nx).toFixed(2) + ',' + (hy - ny).toFixed(2) + ' Z" fill="' + FILL_COLOR + '"/>';
    if (ac - a0 >= 0.05) out += arc(Rt, a0 - ov, ac, FILL_COLOR, fw, 'butt');   // starts under the half disc: no anti-aliasing seam
    out += marker(ac, MARKER_COLOR);
  }
  // center text
  // centre stack (top to bottom): caption, value, unit, peak value
  var vy = cy + (LABEL ? fs * 0.08 : -fs * 0.02);
  if (LABEL) out += '<text x="' + cx + '" y="' + (vy - fs * 0.62).toFixed(2) + '" fill="' + TEXT_COLOR + '" fill-opacity=".7" font-size="' + (LABEL_SIZE * scale).toFixed(1) + '" font-weight="bold" letter-spacing="' + (1.5 * scale).toFixed(1) + '" text-anchor="middle" dominant-baseline="central">' + LABEL + '</text>';
  out += '<text x="' + cx + '" y="' + vy.toFixed(2) + '" fill="' + TEXT_COLOR + '" font-size="' + fs.toFixed(1) + '" font-weight="bold" text-anchor="middle" dominant-baseline="central">' + (typeof cur === 'number' ? cur.toFixed(DIGITS) : '--') + '</text>';
  if (UNIT) out += '<text x="' + cx + '" y="' + (vy + fs * 0.62).toFixed(2) + '" fill="' + TEXT_COLOR + '" fill-opacity=".8" font-size="' + (fs * 0.32).toFixed(1) + '" text-anchor="middle" dominant-baseline="central">' + UNIT + '</text>';
  if (SHOW_PEAK_VAL && alpha > 0) {
    out += '<text x="' + cx + '" y="' + (UNIT ? vy + fs * 0.62 + fs * 0.32 * 0.55 + PEAK_SIZE * scale * 0.6 : vy + fs * 0.62).toFixed(2) + '" fill="' + PEAK_COLOR + '" fill-opacity="' + Math.min(1, alpha / Math.max(PEAK_OPACITY, 0.01)).toFixed(2) + '" font-size="' + (PEAK_SIZE * scale).toFixed(1) + '" font-weight="bold" text-anchor="middle" dominant-baseline="central">MAX ' + peak.toFixed(DIGITS) + '</text>';
  }
  out += '</svg>';
  return out;
}
